/**
 * Mobile crops of the product-page stills.
 *
 * The files are generated by scripts/make-mobile-crops.mjs from the full-size
 * sources in public/, cut from the real UI panel to 4:3. This module is the
 * list of which sources have one, so a component can ask rather than assume:
 * referencing a crop that was never generated would 404 on phones only, which
 * is the kind of bug nobody sees on a laptop.
 *
 * Keep in step with MOBILE_CROP_SOURCES in that script. `npm run crops:check`
 * fails the build when a crop is missing or older than its source.
 */
const SOURCES = [
  '/aiii/ai-brain-hero.webp',
  '/audience-crm-hero.webp',
  '/campaignn.webp',
  '/marketing/customers/customers-outcome-template.png',
  '/marketing/solutions/sol-fashion-inbox.webp',
  '/pnl/39.webp',
  '/warranty-sub-feature/manual-assign.webp',
  '/website-pixel.webp',
] as const;

const HAS_CROP = new Set<string>(SOURCES);

/** The 4:3 crop for a still, or undefined when none was generated. */
export function mobileCropFor(src: string): string | undefined {
  const clean = src.split('?')[0];
  if (!HAS_CROP.has(clean)) return undefined;
  return clean.replace(/\.(png|jpe?g|webp)$/i, '-mobile.webp');
}
